# Find all isolated cells (not adjacent to any same-value cell)
isolated = {}
for r in range(len(result)):
    for c in range(len(result[0])):
        val = result[r][c]
        if val != 5:
            # Check if has any neighbor with same value
            has_neighbor = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(result) and 0 <= nc < len(result[0]):
                        if result[nr][nc] == val:
                            has_neighbor = True
                            break
                if has_neighbor:
                    break

            if not has_neighbor:
                if val not in isolated:
                    isolated[val] = []
                isolated[val].append((r,c))

print("Isolated cells by color:")
for val, pos_list in sorted(isolated.items()):
    print(f"  Color {val}: {pos_list}")

# For colors 1, 2, 4, 6 - connect aligned cells
# Connect vertically in same column, horizontally in same row
for val, pos_list in isolated.items():
    # Group by column for vertical connections
    by_col = {}
    for r, c in pos_list:
        if c not in by_col:
            by_col[c] = []
        by_col[c].append((r, c))

    # Group by row for horizontal connections
    by_row = {}
    for r, c in pos_list:
        if r not in by_row:
            by_row[r] = []
        by_row[r].append((r, c))

    # Draw vertical lines between consecutive cells in each column
    for c, rows in sorted(by_col.items()):
        for i in range(len(rows)-1):
            r1, c1 = rows[i]
            r2, c2 = rows[i+1]
            # Fill between them
            for r in range(r1+1, r2):
                result[r][c1] = val

    # Draw horizontal lines between consecutive cells in each row
    for r, cols in sorted(by_row.items()):
        for i in range(len(cols)-1):
            r1, c1 = cols[i]
            r2, c2 = cols[i+1]
            # Fill between them
            for c in range(c1+1, c2):
                result[r][c] = val

print("\nResult grid:")
import json
print(json.dumps(result))

